/**
 * Type declarations for pdfkit's browser standard-font data modules
 * (exported by the pdfkit package's exports map; not covered by @types/pdfkit).
 */
declare module 'pdfkit/standard-fonts/Helvetica' {
  const Helvetica: { name: string; [key: string]: unknown }
  export default Helvetica
}
declare module 'pdfkit/standard-fonts/HelveticaBold' {
  const HelveticaBold: { name: string; [key: string]: unknown }
  export default HelveticaBold
}
declare module 'pdfkit/standard-fonts/HelveticaOblique' {
  const HelveticaOblique: { name: string; [key: string]: unknown }
  export default HelveticaOblique
}
